import{_ as t,o,c as r,a0 as e}from"./chunks/framework.Caz7a20Z.js";const c=JSON.parse('{"title":"论文基本写完，智能体跑通但还能更香","description":"今天基本把论文写完了，前言重写、方法还要再深改；结果与讨论主要是 AI 写的、偏粗糙；图都画好了很漂亮。物种分布模型智能体跑通了，优化后解决了不少问题，效果仍有提升空间。明天争取改完一遍正文。","frontmatter":{"title":"论文基本写完，智能体跑通但还能更香","date":"2026-08-25T00:00:00.000Z","tags":["日记"],"description":"今天基本把论文写完了，前言重写、方法还要再深改；结果与讨论主要是 AI 写的、偏粗糙；图都画好了很漂亮。物种分布模型智能体跑通了，优化后解决了不少问题，效果仍有提升空间。明天争取改完一遍正文。"},"headers":[],"relativePath":"posts/diary-20260825.md","filePath":"posts/diary-20260825.md","lastUpdated":1787664178000}'),s={name:"posts/diary-20260825.md"};function n(i,a,l,d,h,p){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="论文基本写完-智能体跑通但还能更香" tabindex="-1">论文基本写完，智能体跑通但还能更香 <a class="header-anchor" href="#论文基本写完-智能体跑通但还能更香" aria-label="Permalink to &quot;论文基本写完，智能体跑通但还能更香&quot;">​</a></h1><p>今天是论文推进很猛的一天——<strong>主体内容基本写完了</strong>。先记一记战果，也记一记还没收口的地方。</p><h2 id="论文-骨架基本立起来了" tabindex="-1">论文：骨架基本立起来了 <a class="header-anchor" href="#论文-骨架基本立起来了" aria-label="Permalink to &quot;论文：骨架基本立起来了&quot;">​</a></h2><p>整体往前推了一大步，但各块成色不太一样，得拆开说。</p><h3 id="前言重写了一遍" tabindex="-1">前言重写了一遍 <a class="header-anchor" href="#前言重写了一遍" aria-label="Permalink to &quot;前言重写了一遍&quot;">​</a></h3><p><strong>前言（Introduction）重写了</strong>。之前那版逻辑有点散，今天重新理了叙事线，把&quot;为什么要做、做了什么、亮点在哪&quot;串得更顺。重写这种事一开始嫌烦，改完回头看确实舒服不少。</p><h3 id="方法还得再深改" tabindex="-1">方法还得再深改 <a class="header-anchor" href="#方法还得再深改" aria-label="Permalink to &quot;方法还得再深改&quot;">​</a></h3><p><strong>方法（Methods）部分可能还得深入探讨、再修改一波</strong>。主体有，但有几处的论证深度还不够——现在只是&quot;说清楚了怎么做&quot;，离&quot;说清楚为什么这么做、比别人好在哪&quot;还差口气。这块明天继续抠。</p><h3 id="结果-讨论-ai-写的-偏粗糙" tabindex="-1">结果 &amp; 讨论：AI 写的，偏粗糙 <a class="header-anchor" href="#结果-讨论-ai-写的-偏粗糙" aria-label="Permalink to &quot;结果 &amp; 讨论：AI 写的，偏粗糙&quot;">​</a></h3><p>老实说，<strong>结果（Results）和讨论（Discussion）基本是 AI 帮写的</strong>，目前比较粗糙。好处是框架和措辞一下就铺开了，省了我大量时间；坏处是有些表述浮、有些结论跟我的数据贴得不够紧，得我自己逐段打磨。</p><p>这部分不能全信 AI，明天得一条条过，把不严谨的地方压下去。</p><h3 id="图都画好了-很漂亮" tabindex="-1">图都画好了，很漂亮 <a class="header-anchor" href="#图都画好了-很漂亮" aria-label="Permalink to &quot;图都画好了，很漂亮&quot;">​</a></h3><p><strong>图（Figures）全都画完了，而且很漂亮</strong> ✨。配色、排版、标注都对味，放进去整个论文档次感一下就上来了。图是论文的&quot;门面&quot;，这一步搞定，后面正文修改的底气都足了。</p><h2 id="物种分布模型智能体-跑通了" tabindex="-1">物种分布模型智能体：跑通了！ <a class="header-anchor" href="#物种分布模型智能体-跑通了" aria-label="Permalink to &quot;物种分布模型智能体：跑通了！&quot;">​</a></h2><p>另一个好消息——<strong>物种分布模型智能体终于能跑通了</strong> 🎉。</p><p>不过实话实说，<strong>效果还是有点差强人意</strong>。能跑通是第一步，跑得好是另一回事。今天对它做了一轮<strong>优化，解决了不少问题</strong>：之前卡住的点、输出不规范的坑，都清掉了一批。</p><p>剩下那些&quot;还不够香&quot;的地方，继续调。记一笔：<strong>明天再优化一下</strong>，看看能不能更稳更准。</p><h2 id="明天的计划" tabindex="-1">明天的计划 <a class="header-anchor" href="#明天的计划" aria-label="Permalink to &quot;明天的计划&quot;">​</a></h2><ul><li><strong>正文修改完成一遍</strong>：方法深改 + 结果讨论逐段打磨，争取整体过一遍；</li><li>之后<strong>有时间再整理补充材料（Supplementary）</strong>，把那些细节归拢进去；</li><li>智能体<strong>再优化一轮</strong>，冲更好的效果。</li></ul><hr><p>今天论文主体收尾、智能体跑通，算是很扎实的一天。剩下的收口活儿明天接着干。</p><p>晚安 🌙</p>',22)])])}const g=t(s,[["render",n]]);export{c as __pageData,g as default};
